require_once __DIR__.'/../app.php';require_once __DIR__.'/../ui.php';require_once __DIR__.'/../filters.php';require_admin();[$where,$params]=audit_filters($_GET);$total=(int)scalar("SELECT COUNT(*) FROM activity_logs a WHERE $where",$params);$page=min(max(1,(int)($_GET['page']??1)),max(1,(int)ceil($total/25)));$offset=($page-1)*25;$logs=rows("SELECT a.* FROM activity_logs a WHERE $where ORDER BY a.id DESC LIMIT 25 OFFSET $offset",$params);page_start('Audit trail','Account actions, academic changes, report generation, and backup operations.');
?><section class="panel no-print"><form method="get" class="filter-grid"><?php input_field('q','User / activity keyword',$_GET['q']??'','search',false);$actions=array_column(rows('SELECT DISTINCT action FROM activity_logs ORDER BY action'),'action');select_field('action','Transaction type',array_combine($actions,$actions),$_GET['action']??'',false);$entities=array_column(rows('SELECT DISTINCT entity FROM activity_logs WHERE entity IS NOT NULL ORDER BY entity'),'entity');select_field('entity','Category',array_combine($entities,$entities),$_GET['entity']??'',false);input_field('from','From date',$_GET['from']??'','date',false);input_field('to','To date',$_GET['to']??'','date',false);?><div class="field align-self-end"><button class="btn btn-outline-primary">Filter activity</button></div></form></section><section class="panel"><?php data_table($logs,['id'=>'ID','log_date'=>'Date','log_time'=>'Time','user_id'=>'User ID','full_name'=>'Name','action'=>'Type','activity_description'=>'Activity','ip_address'=>'IP address'],function($r){echo '<details><summary>Before / after</summary><pre>'.h($r['before_data']??'—').'</pre><pre>'.h($r['after_data']??'—').'</pre></details>';});pagination($total,$page,25);?></section><?php page_end();
